// Embeds the brand images used on certificates into a TypeScript module, so PDF
// rendering never depends on reading files at runtime (serverless bundles).
// Source files: public/brand/ (from ayavacreatives.com). Re-run after replacing them:
//   node scripts/certificate-brand-assets.mjs
import { readFileSync, writeFileSync } from 'node:fs'

const files = {
  LOGO_LIGHT_BG: 'public/brand/ayava-logo-light-bg.png',
  MARK_LIGHT_BG: 'public/brand/ayava-mark-light-bg.png',
  MARK_DARK_BG: 'public/brand/ayava-mark-dark-bg.png',
}

const lines = [
  '// Generated by scripts/certificate-brand-assets.mjs from public/brand/ — do not edit by hand.',
  '/* Base64 PNGs; do not format. */',
  '',
]
for (const [name, path] of Object.entries(files)) {
  lines.push(`export const ${name}_PNG = '${readFileSync(path).toString('base64')}'`)
}
writeFileSync('src/server/certificates/brand-assets.ts', lines.join('\n') + '\n')
console.log('wrote src/server/certificates/brand-assets.ts')
